responsePreview:
This Terraform configuration provisions a multi-region AWS RDS MySQL setup with one primary DB instance in `us-west-1` and three cross-region read replicas in `us-east-1`, `eu-central-1`, and `ap-southeast-1`. It also creates a Route 53 hosted zone named `main` and a weighted DNS record that distributes traffic across the three replica database endpoints.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  alias  = "main"
  region = "us-west-1"
}

provider "aws" {
  alias  = "us-east"
  region = "us-east-1"
}

provider "aws" {
  alias  = "eu-central"
  region = "eu-central-1"
}

provider "aws" {
  alias  = "ap-southeast"
  region = "ap-southeast-1"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_password" "db_password" {
  length  = 20
  special = false
}

data "aws_availability_zones" "main" {
  provider = aws.main
  state    = "available"
}

data "aws_availability_zones" "us_east" {
  provider = aws.us-east
  state    = "available"
}

